CREATE TABLE admin (id INTEGER PRIMARY KEY CHECK(id=1), username TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, must_change INTEGER NOT NULL DEFAULT 1, version INTEGER NOT NULL DEFAULT 1, temp_expires INTEGER NOT NULL, consumed INTEGER NOT NULL DEFAULT 0);
CREATE TABLE accounts (id TEXT PRIMARY KEY, name TEXT NOT NULL, provider TEXT NOT NULL, username TEXT NOT NULL, host TEXT NOT NULL, port INTEGER NOT NULL, folders TEXT NOT NULL, secret BLOB, secret_file TEXT NOT NULL DEFAULT '', created_at INTEGER NOT NULL);
CREATE TABLE mailboxes (account_id TEXT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE, name TEXT NOT NULL, uidvalidity INTEGER NOT NULL, synced_at INTEGER NOT NULL, PRIMARY KEY(account_id,name));
CREATE TABLE messages (ref TEXT PRIMARY KEY, account_id TEXT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE, folder TEXT NOT NULL, uidvalidity INTEGER NOT NULL, uid INTEGER NOT NULL, subject TEXT NOT NULL, sender TEXT NOT NULL, sent_at INTEGER NOT NULL, unread INTEGER NOT NULL, size INTEGER NOT NULL, received_at INTEGER NOT NULL DEFAULT 0, flagged INTEGER NOT NULL DEFAULT 0, flags_known INTEGER NOT NULL DEFAULT 0, changed_at INTEGER NOT NULL DEFAULT 0, metadata_version INTEGER NOT NULL DEFAULT 0, recipients TEXT NOT NULL DEFAULT '', cc TEXT NOT NULL DEFAULT '', message_id TEXT NOT NULL DEFAULT '', in_reply_to TEXT NOT NULL DEFAULT '', thread_refs TEXT NOT NULL DEFAULT '', list_id TEXT NOT NULL DEFAULT '', has_attachment INTEGER NOT NULL DEFAULT 0, UNIQUE(account_id,folder,uidvalidity,uid));
CREATE TABLE folder_settings(account_id TEXT PRIMARY KEY REFERENCES accounts(id) ON DELETE CASCADE,archive_folder TEXT NOT NULL DEFAULT '',trash_folder TEXT NOT NULL DEFAULT '',writes_enabled INTEGER NOT NULL DEFAULT 0,version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE operation_plans(id TEXT PRIMARY KEY,owner TEXT NOT NULL,payload TEXT NOT NULL,created_at INTEGER NOT NULL,expires INTEGER NOT NULL,settings_version INTEGER NOT NULL);
CREATE TABLE operations(id TEXT PRIMARY KEY,plan_id TEXT NOT NULL UNIQUE REFERENCES operation_plans(id),owner TEXT NOT NULL,idempotency_key TEXT NOT NULL,state TEXT NOT NULL,cancelled INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL, cancel_source TEXT NOT NULL DEFAULT '',UNIQUE(owner,idempotency_key));
CREATE TABLE operation_items(operation_id TEXT NOT NULL REFERENCES operations(id) ON DELETE CASCADE,position INTEGER NOT NULL,ref TEXT NOT NULL,state TEXT NOT NULL,error_code TEXT NOT NULL DEFAULT '',before_labels TEXT NOT NULL DEFAULT '[]',destination TEXT NOT NULL DEFAULT '',destination_validity INTEGER NOT NULL DEFAULT 0,destination_uid INTEGER NOT NULL DEFAULT 0, detail TEXT NOT NULL DEFAULT '', recovery_code TEXT NOT NULL DEFAULT '', recovery_detail TEXT NOT NULL DEFAULT '', checked_at INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(operation_id,position));
PRAGMA user_version=14;
